def bowling_score(rolls) -> int:
    if not isinstance(rolls, list) or any(
        not isinstance(r, int) or r < 0 or r > 10 for r in rolls
    ):
        raise ValueError("Invalid roll values")

    score = 0
    idx = 0
    for frame in range(9):
        if idx >= len(rolls):
            raise ValueError("Too few rolls")
        if rolls[idx] == 10:
            if idx + 2 >= len(rolls):
                raise ValueError("Not enough rolls for strike bonus")
